// Fail-closed verification of webhook secret and content generation/publishing payload
const headers = $input.item.json.headers || {};
const secretHeader = headers['x-webhook-secret'] || headers['X-Webhook-Secret'];
const expectedSecret = ('45e76db89ee5ca001af20a4c23ebb4a898bebe04157cb677b9b256c3fc639e24').trim();

if (!expectedSecret) {
  return {
    isValid: false,
    statusCode: 500,
    error: 'Server configuration error: N8N_WEBHOOK_SECRET is not configured on server.'
  };
}

if (!secretHeader || secretHeader !== expectedSecret) {
  return {
    isValid: false,
    statusCode: 401,
    error: 'Unauthorized: Invalid or missing webhook shared secret.'
  };
}

const body = $input.item.json.body || {};
const action = (body.action || 'generate').trim().toLowerCase();

if (!['generate', 'publish'].includes(action)) {
  return {
    isValid: false,
    statusCode: 400,
    error: 'Bad Request: action must be either "generate" or "publish".'
  };
}

if (action === 'generate') {
  const sourcePrompt = typeof body.sourcePrompt === 'string' ? body.sourcePrompt.trim() : '';
  if (!sourcePrompt || sourcePrompt.length < 10) {
    return {
      isValid: false,
      statusCode: 400,
      error: 'Bad Request: sourcePrompt must be at least 10 characters describing the research or announcement.'
    };
  }

  const allowedTypes = ['research_update', 'event_announcement', 'project_findings'];
  const contentType = (body.contentType || 'research_update').trim();
  if (!allowedTypes.includes(contentType)) {
    return {
      isValid: false,
      statusCode: 400,
      error: 'Bad Request: contentType must be one of: research_update, event_announcement, project_findings.'
    };
  }

  const targetChannels = Array.isArray(body.targetChannels) && body.targetChannels.length > 0
    ? body.targetChannels
    : ['website', 'linkedin', 'newsletter'];

  return {
    isValid: true,
    action: 'generate',
    sourcePrompt,
    contentType,
    additionalInstructions: body.additionalInstructions || '',
    targetChannels
  };
}

// action === 'publish'
const postId = typeof body.postId === 'string' ? body.postId.trim() : '';
if (!postId) {
  return {
    isValid: false,
    statusCode: 400,
    error: 'Bad Request: postId is required for publish action.'
  };
}

const channels = Array.isArray(body.channels) && body.channels.length > 0
  ? body.channels
  : null;

return {
  isValid: true,
  action: 'publish',
  postId,
  channels
};

const response = $input.item.json;
const prev = $('Route Action').first().json;

let rawText = '';
if (typeof response?.output === 'string') {
  rawText = response.output;
} else if (typeof response?.text === 'string') {
  rawText = response.text;
} else if (response?.candidates?.[0]?.content?.parts?.[0]?.text) {
  rawText = response.candidates[0].content.parts[0].text;
} else if (typeof response === 'string') {
  rawText = response;
} else {
  throw new Error('Gemini API returned an invalid or empty response structure.');
}

let cleaned = rawText.trim();
if (cleaned.startsWith('```json')) {
  cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
} else if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
}

let data = {};
try {
  data = JSON.parse(cleaned.trim());
} catch (e) {
  throw new Error('Failed to parse Gemini output as JSON: ' + rawText.slice(0, 100));
}

const title = (data.title || 'Impact Circles Announcement').trim().slice(0, 255);

const linkedinPostText = (data.linkedin?.postText || data.linkedin?.content || '').trim();
const linkedinHashtags = Array.isArray(data.linkedin?.hashtags) ? data.linkedin.hashtags : ['#ImpactCircles'];
const linkedin = {
  postText: linkedinPostText,
  content: linkedinPostText,
  hashtags: linkedinHashtags,
  characterCount: linkedinPostText.length
};

const newsletterSubject = (data.newsletter?.subject || title).trim();
const newsletterPreview = (data.newsletter?.previewText || data.newsletter?.preview || data.newsletter?.summary || '').trim();
const newsletterBody = (data.newsletter?.bodyText || data.newsletter?.body || data.newsletter?.summary || '').trim();
const newsletterCta = (data.newsletter?.callToAction || data.newsletter?.cta || 'Read more').trim();
const newsletter = {
  subject: newsletterSubject,
  previewText: newsletterPreview,
  preview: newsletterPreview,
  bodyText: newsletterBody,
  body: newsletterBody,
  callToAction: newsletterCta,
  cta: newsletterCta,
  summary: newsletterPreview || newsletterBody
};

const websiteTitle = (data.website?.title || title).trim();
const websiteSubtitle = (data.website?.subtitle || data.website?.excerpt || data.summary || '').trim();
const websiteSlug = (data.website?.slug || title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '')).trim();
const websiteMarkdown = (data.website?.bodyMarkdown || data.website?.markdownContent || data.website?.markdown || '').trim();
const websiteTags = Array.isArray(data.website?.tags) ? data.website.tags : ['Research'];
const website = {
  title: websiteTitle,
  subtitle: websiteSubtitle,
  excerpt: websiteSubtitle,
  slug: websiteSlug,
  bodyMarkdown: websiteMarkdown,
  markdownContent: websiteMarkdown,
  tags: websiteTags
};

const generatedId = 'cp_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);

return {
  id: generatedId,
  title,
  sourcePrompt: prev.sourcePrompt,
  contentType: prev.contentType,
  status: 'draft',
  linkedinContent: JSON.stringify(linkedin),
  newsletterContent: JSON.stringify(newsletter),
  websiteContent: JSON.stringify(website),
  targetChannels: JSON.stringify(prev.targetChannels),
  metadata: JSON.stringify({
    summary: data.summary || websiteSubtitle || '',
    generatedVia: 'n8n_gemini_agent',
    generatedAt: new Date().toISOString()
  })
};

const record = $input.item.json;
if (!record || !record.id) {
  throw new Error('Database persistence failed to return a valid content post.');
}

return {
  success: true,
  post: record
};

const post = $input.item.json;
const req = $('Route Action').first().json;

if (!post || !post.id) {
  return {
    canPublish: false,
    statusCode: 404,
    error: 'Not Found: Content post with ID ' + req.postId + ' does not exist.'
  };
}

if (post.status !== 'approved') {
  return {
    canPublish: false,
    statusCode: 400,
    error: 'Strict Invariant Violation: Content post cannot be published unless it has been explicitly approved by a human reviewer. Current status is "' + post.status + '".'
  };
}

let targetChannels = [];
if (Array.isArray(req.channels) && req.channels.length > 0) {
  targetChannels = req.channels;
} else if (Array.isArray(post.targetChannels)) {
  targetChannels = post.targetChannels;
} else if (typeof post.targetChannels === 'string') {
  try {
    targetChannels = JSON.parse(post.targetChannels);
  } catch (e) {
    targetChannels = ['website', 'linkedin', 'newsletter'];
  }
} else {
  targetChannels = ['website', 'linkedin', 'newsletter'];
}

const logs = [];
const timestamp = Date.now();

for (const ch of targetChannels) {
  const logId = 'log_' + timestamp.toString(36) + '_' + ch + '_' + Math.random().toString(36).substring(2, 6);
  let publishedUrl = null;
  let responsePayload = {};

  if (ch === 'website') {
    let slug = 'announcement-' + timestamp;
    try {
      const web = JSON.parse(post.websiteContent || '{}');
      if (web.slug) slug = web.slug;
    } catch (e) {}
    publishedUrl = 'https://impactcircles.org/news/' + slug;
    responsePayload = { provider: 'Website CMS', slug, mode: 'live_synced' };
  } else if (ch === 'linkedin') {
    publishedUrl = 'https://www.linkedin.com/feed/update/urn:li:share:' + (timestamp + 1000000);
    responsePayload = { provider: 'LinkedIn Marketing API', urn: 'urn:li:share:' + (timestamp + 1000000), mode: 'simulated_sandbox' };
  } else if (ch === 'newsletter') {
    publishedUrl = 'https://impactcircles.substack.com/p/digest-' + timestamp;
    responsePayload = { provider: 'Newsletter Email Broadcast', campaignId: 'camp_' + timestamp, mode: 'simulated_sandbox' };
  }

  logs.push({
    id: logId,
    post_id: post.id,
    postId: post.id,
    channel: ch,
    status: 'success',
    published_url: publishedUrl,
    publishedUrl,
    response_payload: JSON.stringify(responsePayload),
    responsePayload: JSON.stringify(responsePayload),
    error_message: null,
    errorMessage: null
  });
}

return {
  canPublish: true,
  postId: post.id,
  targetChannels,
  logs,
  logsJson: JSON.stringify(logs),
  newStatus: 'published'
};

const updatedPost = $input.item.json;
const prev = $('Verify Human Approval & Execute Dispatch').first().json;

return {
  success: true,
  postId: prev.postId,
  status: updatedPost.status || 'published',
  publishedChannels: prev.targetChannels,
  logs: prev.logs
};

const item = $input.item.json;
const errObj = item?.error || item;
const errStatus = Number(errObj?.status || errObj?.statusCode || 0);
const rawMessage = String(errObj?.message || errObj?.description || item?.message || '');

const isRateLimit =
  errStatus === 429 ||
  rawMessage.includes('429') ||
  rawMessage.toLowerCase().includes('too many requests') ||
  rawMessage.toLowerCase().includes('quota');

const isUnavailable =
  errStatus === 503 ||
  rawMessage.includes('503') ||
  rawMessage.toLowerCase().includes('service unavailable');

let statusCode = 502;
let safeMessage = 'AI content generation service failed to produce content.';

if (isRateLimit) {
  statusCode = 429;
  safeMessage = 'AI content generation rate limit reached. Please retry shortly.';
} else if (isUnavailable) {
  statusCode = 503;
  safeMessage = 'AI content generation service temporarily unavailable. Please retry shortly.';
}

return {
  success: false,
  error: safeMessage,
  statusCode
};

return {
  success: false,
  error: 'Database operation failed during content pipeline execution. Please try again.',
  statusCode: 500
};

